namespace BlazorNotifications.Services;

public record Notification(int Id, string Message, DateTime Timestamp);

public class NotificationService
{
    private int _nextId = 4;
    private readonly List<Notification> _notifications = new()
    {
        new(1, "Welcome to the app!", DateTime.UtcNow.AddMinutes(-10)),
        new(2, "Your profile was updated.", DateTime.UtcNow.AddMinutes(-5)),
        new(3, "New feature available: Dark Mode.", DateTime.UtcNow.AddMinutes(-1)),
    };

    /// <summary>
    /// Returns all current notifications (used for initial load).
    /// </summary>
    public Task<List<Notification>> GetAllAsync()
    {
        lock (_notifications)
        {
            return Task.FromResult(_notifications.ToList());
        }
    }

    /// <summary>
    /// Returns notifications created after the given timestamp.
    /// Simulates new notifications arriving occasionally.
    /// </summary>
    public Task<List<Notification>> GetNewSinceAsync(DateTime since)
    {
        // Simulate a new notification roughly every other call
        lock (_notifications)
        {
            if (Random.Shared.Next(2) == 0)
            {
                var n = new Notification(
                    _nextId++,
                    $"New event at {DateTime.UtcNow:T}",
                    DateTime.UtcNow);
                _notifications.Add(n);
            }

            return Task.FromResult(
                _notifications.Where(n => n.Timestamp > since).ToList());
        }
    }
}

